"""Exercise the leased production flow body with isolated synthetic rows and rules."""
from pathlib import Path
R=Path(__file__).resolve().parents[2]
print('BEGIN;\nCREATE SCHEMA v361_fixture;\nCREATE TABLE v361_fixture.rows(user_id uuid,event_date date,account text,description text,signed_amount numeric,source text,source_ref text,confidence text,account_assignment text,legacy_index integer,original_date date,displaced boolean);\nCREATE TABLE v361_fixture.card_invoices(user_id uuid,card_name text,reference_month date,metadata jsonb);\nCREATE TABLE v361_fixture.lts_card_due_rule_v290(user_id uuid,family text,effective_from date,due_day integer,PRIMARY KEY(user_id,family,effective_from));\nCREATE FUNCTION v361_fixture.lts_corrected_cashflow_fix86_v4(uuid,date,date)\nRETURNS TABLE(event_date date,account text,description text,signed_amount numeric,source text,source_ref text,confidence text,account_assignment text,legacy_index integer,original_date date,displaced boolean)\nLANGUAGE sql AS $$SELECT event_date,account,description,signed_amount,source,source_ref,confidence,account_assignment,legacy_index,original_date,displaced FROM v361_fixture.rows WHERE user_id=$1 AND event_date BETWEEN $2 AND $3$$;\nINSERT INTO v361_fixture.rows\nSELECT \'00000000-0000-4000-8000-000000000001\',d,\'Bradesco\',\'Visa Aeternum\',-10,\'legacy_fix86\',\'legacy:\'||n,\'legacy_projection_adjusted\',\'assigned\',n,d,false\nFROM(VALUES(1,date\'2026-10-25\'),(2,date\'2026-11-25\'),(3,date\'2026-12-25\'),(4,date\'2027-01-25\'),(5,date\'2027-10-25\'))x(n,d);\nINSERT INTO v361_fixture.rows\nSELECT \'00000000-0000-4000-8000-000000000001\',\'2026-12-25\',account,description,amount,source,\'other:\'||n,confidence,\'assigned\',n,\'2026-12-25\',displaced\nFROM(VALUES\n (6,\'Bradesco\',\'Mastercard\',-11,\'legacy_fix86\',\'legacy_projection_adjusted\',false),\n (7,\'C6\',\'Visa Aeternum\',-12,\'legacy_fix86\',\'legacy_projection_adjusted\',false),\n (8,\'Bradesco\',\'Visa Aeternum\',-13,\'current_event\',\'user_flow_editable\',false),\n (9,\'Bradesco\',\'Visa Aeternum\',-14,\'confirmed_fact\',\'user_confirmed_fact\',false),\n (10,\'Bradesco\',\'Visa Aeternum\',15,\'legacy_fix86\',\'legacy_projection_adjusted\',false),\n (11,\'Bradesco\',\'Visa Aeternum\',-16,\'legacy_fix86\',\'historical_workbook_signed_adjustment\',false),\n (12,\'Bradesco\',\'Visa Aeternum\',-17,\'legacy_fix86\',\'legacy_projection_adjusted\',true),\n (13,\'Bradesco\',\'Visa Aeternum\',-18,\'legacy_fix86\',\'bank_documented_settlement_precedence\',false)\n)x(n,account,description,amount,source,confidence,displaced);\nINSERT INTO v361_fixture.rows VALUES\n (\'00000000-0000-4000-8000-000000000001\',\'2026-12-25\',\'Bradesco\',\'Fatura Visa Aeternum\',-19,\'card_invoice\',\'Visa Aeternum|2026-12\',\'documented_open\',\'assigned\',null,\'2026-12-25\',false),\n (\'00000000-0000-4000-8000-000000000002\',\'2026-12-25\',\'Bradesco\',\'Visa Aeternum\',-20,\'legacy_fix86\',\'other-owner\',\'legacy_projection_adjusted\',\'assigned\',20,\'2026-12-25\',false);\nINSERT INTO v361_fixture.card_invoices VALUES(\'00000000-0000-4000-8000-000000000001\',\'Visa Aeternum\',\'2026-12-01\',\'{"cash_effect_date":"2026-12-08"}\');\nINSERT INTO v361_fixture.lts_card_due_rule_v290 VALUES\n (\'00000000-0000-4000-8000-000000000001\',\'aeternum\',\'2026-12-01\',3),\n (\'00000000-0000-4000-8000-000000000001\',\'aeternum\',\'2027-01-01\',6);\n')
print((R/'backend/qa/fixtures/v361_cashflow_v5.sql').read_text().replace('public.','v361_fixture.')+';')
print(r"""
REVOKE ALL ON FUNCTION v361_fixture.lts_corrected_cashflow_fix86_v5(uuid,date,date)FROM PUBLIC;
GRANT EXECUTE ON FUNCTION v361_fixture.lts_corrected_cashflow_fix86_v5(uuid,date,date)TO service_role;
CREATE TEMP TABLE v361_before AS SELECT jsonb_agg(to_jsonb(x)ORDER BY source_ref)j FROM v361_fixture.lts_corrected_cashflow_fix86_v5('00000000-0000-4000-8000-000000000001','2026-10-01','2027-10-31')x;
CREATE TEMP TABLE v361_attrs AS SELECT to_jsonb(p)-'prosrc'j FROM pg_proc p WHERE oid='v361_fixture.lts_corrected_cashflow_fix86_v5(uuid,date,date)'::regprocedure;
CREATE TEMP TABLE v361_raw AS SELECT jsonb_build_object('rows',(SELECT jsonb_agg(to_jsonb(x)ORDER BY source_ref)FROM v361_fixture.rows x),'rules',(SELECT jsonb_agg(to_jsonb(x)ORDER BY effective_from)FROM v361_fixture.lts_card_due_rule_v290 x),'invoices',(SELECT jsonb_agg(to_jsonb(x))FROM v361_fixture.card_invoices x))j;
""")
patch=(R/'backend/patches/v361/effective_legacy_card_due.sql').read_text().replace('public.','v361_fixture.')
patch=patch.replace('md5(definition)',"md5(replace(definition,'v361_fixture.','public.'))").replace('md5(restored)',"md5(replace(restored,'v361_fixture.','public.'))")
print(patch)
print("\nDO $test$DECLARE u uuid:='00000000-0000-4000-8000-000000000001';d date;a jsonb;b jsonb;BEGIN\n IF(SELECT jsonb_agg(to_jsonb(x)ORDER BY source_ref)FROM v361_fixture.lts_corrected_cashflow_fix86_v5(u,'2026-10-01','2027-10-31')x WHERE legacy_index NOT IN(3,4,5)OR legacy_index IS NULL)\n IS DISTINCT FROM(SELECT jsonb_agg(x ORDER BY x->>'source_ref')FROM v361_before CROSS JOIN LATERAL jsonb_array_elements(j)x WHERE(x->>'legacy_index')::int NOT IN(3,4,5)OR x->>'legacy_index'IS NULL)\n THEN RAISE EXCEPTION 'Unrelated flow changed';END IF;\n IF(SELECT count(*)FROM v361_fixture.lts_corrected_cashflow_fix86_v5(u,'2026-12-03','2026-12-03')WHERE source_ref='legacy:3'AND displaced AND original_date='2026-12-25')<>1\n THEN RAISE EXCEPTION 'Moved forecast missing from narrow new day';END IF;\n IF EXISTS(SELECT 1 FROM v361_fixture.lts_corrected_cashflow_fix86_v5(u,'2026-12-25','2026-12-25')WHERE source_ref='legacy:3')\n THEN RAISE EXCEPTION 'Moved forecast duplicated on original day';END IF;\n IF(SELECT count(*)FROM v361_fixture.lts_corrected_cashflow_fix86_v5(u,'2027-01-06','2027-01-06')WHERE source_ref='legacy:4')<>1\n OR(SELECT count(*)FROM v361_fixture.lts_corrected_cashflow_fix86_v5(u,'2027-10-06','2027-10-06')WHERE source_ref='legacy:5')<>1\n THEN RAISE EXCEPTION 'Latest effective rule or later legacy month missed';END IF;\n IF(SELECT event_date FROM v361_fixture.lts_corrected_cashflow_fix86_v5('00000000-0000-4000-8000-000000000002','2026-12-01','2026-12-31'))<>'2026-12-25'\n THEN RAISE EXCEPTION 'Other owner rule leaked';END IF;\n IF(SELECT sum(signed_amount)FROM v361_fixture.lts_corrected_cashflow_fix86_v5(u,'2026-10-01','2027-10-31'))\n IS DISTINCT FROM(SELECT sum((x->>'signed_amount')::numeric)FROM v361_before CROSS JOIN LATERAL jsonb_array_elements(j)x)\n THEN RAISE EXCEPTION 'Total changed';END IF;\n FOR d IN SELECT generate_series('2026-11-01'::date,'2027-02-01'::date,'1 day')::date LOOP\n  SELECT coalesce(jsonb_agg(to_jsonb(x)ORDER BY source_ref),'[]')INTO a FROM v361_fixture.lts_corrected_cashflow_fix86_v5(u,d,d)x;\n  SELECT coalesce(jsonb_agg(to_jsonb(x)ORDER BY source_ref),'[]')INTO b FROM v361_fixture.lts_corrected_cashflow_fix86_v5(u,'2026-10-01','2027-10-31')x WHERE event_date=d;\n  IF a IS DISTINCT FROM b THEN RAISE EXCEPTION 'Slice/full mismatch for %',d;END IF;\n END LOOP;\n IF(SELECT j FROM v361_attrs)IS DISTINCT FROM(SELECT to_jsonb(p)-'prosrc'FROM pg_proc p WHERE oid='v361_fixture.lts_corrected_cashflow_fix86_v5(uuid,date,date)'::regprocedure)\n THEN RAISE EXCEPTION 'Function ACL/security attributes changed';END IF;\n IF(SELECT j FROM v361_raw)IS DISTINCT FROM jsonb_build_object('rows',(SELECT jsonb_agg(to_jsonb(x)ORDER BY source_ref)FROM v361_fixture.rows x),'rules',(SELECT jsonb_agg(to_jsonb(x)ORDER BY effective_from)FROM v361_fixture.lts_card_due_rule_v290 x),'invoices',(SELECT jsonb_agg(to_jsonb(x))FROM v361_fixture.card_invoices x))\n THEN RAISE EXCEPTION 'Underlying data mutated';END IF;\nEND $test$;\nCREATE TEMP TABLE v361_replay AS SELECT pg_get_functiondef('v361_fixture.lts_corrected_cashflow_fix86_v5(uuid,date,date)'::regprocedure)definition;\n")
print(patch)
print(r"""
DO $test$BEGIN
IF(SELECT definition FROM v361_replay)IS DISTINCT FROM pg_get_functiondef('v361_fixture.lts_corrected_cashflow_fix86_v5(uuid,date,date)'::regprocedure)THEN RAISE EXCEPTION 'Replay changed definition';END IF;
END $test$;
SELECT jsonb_build_object('version',361,'pass',true,'synthetic_rows',15,'daily_slice_checks',93,'amounts_preserved',true,'official_cash_date_preserved',true,'other_owner_preserved',true,'raw_preserved',true,'function_attributes_preserved',true,'replay_noop',true);
ROLLBACK;
""")
